29	  /// Parses [Plugin] specification from the provided pluginYaml.
30	  ///
31	  /// This currently supports two formats. Legacy and Multi-platform.
32	  ///
33	  /// Example of the deprecated Legacy format.
34	  ///
35	  ///     flutter:
36	  ///      plugin:
37	  ///        androidPackage: io.flutter.plugins.sample
38	  ///        iosPrefix: FLT
39	  ///        pluginClass: SamplePlugin
40	  ///
41	  /// Example Multi-platform format.
42	  ///
43	  ///     flutter:
44	  ///      plugin:
45	  ///        platforms:
46	  ///          android:
47	  ///            package: io.flutter.plugins.sample
48	  ///            pluginClass: SamplePlugin
49	  ///          ios:
50	  ///            pluginClass: SamplePlugin
51	  ///          linux:
52	  ///            pluginClass: SamplePlugin
53	  ///          macos:
54	  ///            pluginClass: SamplePlugin
55	  ///          windows:
